 * Composer install script and no provider boot step copies files into the
 * consumer's `public/`, `resources/` or any other application directory.
 */";s:65:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespaceUses";O:30:"PHPStan\Analyser\NamespaceUses":3:{s:9:"namespace";s:15:"Sahil\Firefiber";s:4:"uses";a:21:{s:9:"container";s:25:"Sahil\Container\Container";s:20:"assetmanagercontract";s:43:"Sahil\Contracts\Assets\AssetManagerContract";s:13:"cachecontract";s:35:"Sahil\Contracts\Cache\CacheContract";s:19:"applicationcontract";s:46:"Sahil\Contracts\Foundation\ApplicationContract";s:15:"sessioncontract";s:39:"Sahil\Contracts\Session\SessionContract";s:15:"storagecontract";s:39:"Sahil\Contracts\Storage\StorageContract";s:25:"componentrenderercontract";s:46:"Sahil\Contracts\View\ComponentRendererContract";s:12:"viewcontract";s:33:"Sahil\Contracts\View\ViewContract";s:15:"assetrepository";s:38:"Sahil\Firefiber\Assets\AssetRepository";s:21:"firefiberassetmanager";s:44:"Sahil\Firefiber\Assets\FirefiberAssetManager";s:13:"runtimeassets";s:36:"Sahil\Firefiber\Assets\RuntimeAssets";s:15:"assetcontroller";s:36:"Sahil\Firefiber\Http\AssetController";s:25:"firefiberactioncontroller";s:46:"Sahil\Firefiber\Http\FirefiberActionController";s:19:"firefibermiddleware";s:40:"Sahil\Firefiber\Http\FirefiberMiddleware";s:22:"filecachereplaystorage";s:46:"Sahil\Firefiber\Storage\FileCacheReplayStorage";s:21:"filecachestatestorage";s:45:"Sahil\Firefiber\Storage\FileCacheStateStorage";s:22:"replaystorageinterface";s:46:"Sahil\Firefiber\Storage\ReplayStorageInterface";s:21:"statestorageinterface";s:45:"Sahil\Firefiber\Storage\StateStorageInterface";s:15:"serviceprovider";s:32:"Sahil\Foundation\ServiceProvider";s:4:"link";s:18:"Sahil\Routing\Link";s:6:"router";s:17:"Sahil\Http\Router";}s:9:"constUses";a:0:{}}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";s:32:"Sahil\Foundation\ServiceProvider";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61: